import{z as s,x as p,o as r,c as n,q as A,j as o,D as e,d as a,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"奖励过优化的理论视角","description":"","frontmatter":{"title":"奖励过优化的理论视角","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reward-overoptimization-theory.md","filePath":"llm/reward-overoptimization-theory.md","lastUpdated":1791063341000}'),d={name:"llm/reward-overoptimization-theory.md"};function m(h,E,C,F,D,b){const B=p("Mermaid");return r(),n("div",null,[E[2]||(E[2]=A('<h1 id="奖励过优化的理论视角" tabindex="-1">奖励过优化的理论视角 <a class="header-anchor" href="#奖励过优化的理论视角" aria-label="Permalink to &quot;奖励过优化的理论视角&quot;">​</a></h1><div class="epigraph"><p>度量一旦成为目标就不再是好度量；优化器不会停在相关性失效的地方，它专门去那里。</p><footer>—— Strathern 1997 对 Goodhart 定律的表述；理论骨架据 Skalse 等 2022、Gao 等 2022 整理</footer></div><p><a href="/llm/offline-rl-shift">上一课</a>把保守主义的动机钉在「数据支撑外价值不可信」上，并指出 RLHF 里离线的是奖励来源。<a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a> 已画过实证曲线：代理奖励一路涨，金标先升后降，更大的 RM 只推迟拐点。本课补理论骨架：间隙从哪来、优化压力如何放大间隙、哪些量可以被监控。实证课给形状，本课给可以推导的骨头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设真实奖励 \\(r^\\star\\)（人类抽检、更大 RM、任务通过率）与代理 \\(\\tilde r\\)（训练出的 RM）。写恒等式</p> \\[\\mathbb{E}_\\pi[r^\\star]=\\mathbb{E}_\\pi[\\tilde r]+\\mathbb{E}_\\pi[\\eta],\\qquad \\eta=r^\\star-\\tilde r, \\]<p>\\(\\eta\\) 是残差。\\(\\tilde r\\) 在离线比较数据上拟合，残差里藏着捷径：长度、清单、客套、表面正确。关键不在残差存在，而在<strong>残差与代理相关</strong>：两者被同一批捷径驱动，\\(\\tilde r\\) 高分处 \\(\\eta\\) 系统性偏正还是偏负并不对称——把 \\(\\pi\\) 推向 \\(\\tilde r\\) 的高分尾部，落点集中在 \\(\\eta\\) 最偏正的样本附近，于是 \\(\\mathbb{E}_\\pi[r^\\star]\\) 先随 \\(\\mathbb{E}_\\pi[\\tilde r]\\) 上升、后被负的 \\(\\mathbb{E}_\\pi[\\eta]\\) 拖垮。Goodhart 的变体分类里（回归式、极值式、因果式、对抗式），RL 撞的是极值式：优化不是被动选一个点，而是主动搜索相关性最失效的尾部。</p><p><span class="marginnote">数字实例：设某批候选里「真好」的占七成，被动均匀抽一个期望不坏；优化器却专到 \\(\\tilde r\\) 最高分的那一小撮里挑——长、客套这类捷径样本恰好在高分端扎堆，这一撮里「真好」的比例可能掉到三成。「残差与代理相关」的通俗版就是：哪里相关性失效，优化器就住到哪里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三块骨架，各对应一个可操作的量。其一，<strong>优化压力旋钮</strong>。KL 正则目标</p> \\[\\max_\\pi\\ \\mathbb{E}_\\pi[\\tilde r]-\\beta\\,\\mathrm{KL}(\\pi\\,\\|\\,\\pi_{\\mathrm{ref}}) \\]<p>的解形如 \\(\\pi\\propto\\pi_{\\mathrm{ref}}\\exp(\\tilde r/\\beta)\\)：\\(\\beta\\) 调小、PPO 步数加长、Best-of-N 的 \\(N\\) 调大，都在给 \\(\\exp\\) 的指数加压，策略向 \\(\\tilde r\\) 的极值集中（实现见 <a href="/llm/ppo-llm">PPO 在语言模型中的实现</a>）。其二，<strong>标度律骨架</strong>。Gao 等把「代理减金标」之差对优化强度（KL、\\(N\\)）的曲线在 RL 与 Best-of-N 两条路线上拟合出同族形状，系数随 RM 与金标的规模差变化——金标越强、间隙涨得越慢，但拐点只被推迟。其三，<strong>可钻性的形式化</strong>。Skalse 等把 reward hacking 写成：若存在策略使代理高、真奖励低，代理就是可钻的；可钻性是常态而非病态，问题只是优化器离它多近。</p><p><span class="marginnote">Gao 等的曲线里 RL 与 Best-of-N 同形，但 RL 到拐点更快：同样一份优化强度预算，交给 PPO 比交给推理期选择更早透支代理的信用。</span></p><p><span class="marginnote">术语翻译：\\(\\pi\\propto\\pi_{\\mathrm{ref}}\\exp(\\tilde r/\\beta)\\) 读作「新策略 = 参考策略按奖励指数加权」。\\(\\beta=1\\) 时指数平缓，策略几乎不动；\\(\\beta\\) 降到 \\(0.1\\)，同样的奖励差被放大十倍，样本便涌向高分端。\\(\\beta\\)、PPO 步数、BoN 的 \\(N\\) 拧的是同一个指数的陡度，所以它们是同一种「压力」的三种货币。</span></p>',14)),(r(),o(l,null,{default:e(()=>[i(B,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E7%A6%BB%E7%BA%BF%E6%AF%94%E8%BE%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20RM%5B%22%E4%BB%A3%E7%90%86%E5%A5%96%E5%8A%B1%20r%CC%83%EF%BC%88%E6%AE%8B%E5%B7%AE%20%CE%B7%20%E8%97%8F%E6%8D%B7%E5%BE%84%EF%BC%89%22%5D%0A%20%20PRESS%5B%22%E4%BC%98%E5%8C%96%E5%8E%8B%E5%8A%9B%EF%BC%9A%E5%B0%8F%20%CE%B2%E3%80%81%E5%A4%9A%E6%AD%A5%E3%80%81%E5%A4%A7%20N%22%5D%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%E8%A2%AB%20exp%20%E9%A1%B9%E6%8E%A8%E5%90%91%20r%CC%83%20%E6%9E%81%E5%80%BC%22%5D%0A%20%20RM%20--%3E%20PI%0A%20%20PI%20--%3E%20TAIL%5B%22%E7%A6%BB%E5%BC%80%E6%95%B0%E6%8D%AE%E6%94%AF%E6%92%91%E7%9A%84%E5%B0%BE%E9%83%A8%22%5D%0A%20%20TAIL%20--%3E%20NEG%5B%22%E6%9C%9F%E6%9C%9B%20%CE%B7%20%E5%8F%98%E8%B4%9F%EF%BC%9A%E9%87%91%E6%A0%87%E5%9B%9E%E8%90%BD%22%5D%0A%20%20KLB%5B%22KL%20%E6%AD%A3%E5%88%99%20%CE%B2%20%E7%BB%99%E5%8E%8B%E5%8A%9B%E5%AE%9A%E4%BB%B7%22%5D%20--%3E%20PRESS%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("三块骨架扣回上一课的离线视角：RM 是离线拟合的，策略被优化压力推离数据支撑，支撑外残差 \\(\\eta\\) 无约束——所以 Goodhart 放大 = 优化 × 外推，不是两个独立毛病，是同一台机器的两个齿轮。这解释了几件事为何有效、为何有限。KL 有用，因为它直接给压力定价：\\(\\beta\\) 是唯一标了价的旋钮。集成与校准（下一课程展开）只能挪拐点：它们压小 \\(\\eta\\) 的方差，不改变极值处相关性失效。RLVR 也不是解药：把 \\(\\tilde r\\) 换成验证器（"),t("a",{href:"/llm/rlvr"},"RLVR"),a("）消灭了 RM 的间隙，验证器自己成为新代理——奖励黑客换了宿主（"),t("a",{href:"/llm/reward-hacking-llm"},"奖励黑客"),a("），GRPO 组内同一验证器的奖励照样能被格式与猜测攻击吃掉。")],-1)),(r(),o(l,null,{default:e(()=>[i(B,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22RM%20%E7%A6%BB%E7%BA%BF%E6%8B%9F%E5%90%88%EF%BC%9A%E6%94%AF%E6%92%91%E5%A4%96%20%CE%B7%20%E6%97%A0%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20G1%5B%22%E9%BD%BF%E8%BD%AE%E4%B8%80%EF%BC%9A%E5%A4%96%E6%8E%A8%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20PRESS%5B%22%E4%BC%98%E5%8C%96%E5%8E%8B%E5%8A%9B%EF%BC%9Aexp%20%E5%8A%A0%E5%8E%8B%22%5D%20--%3E%20G2%5B%22%E9%BD%BF%E8%BD%AE%E4%BA%8C%EF%BC%9A%E6%90%9C%E5%90%91%E6%9E%81%E5%80%BC%E5%B0%BE%E9%83%A8%22%5D%0A%20%20G1%20--%3E%20G%5B%22Goodhart%20%E6%94%BE%E5%A4%A7%EF%BC%9A%E9%87%91%E6%A0%87%E5%85%88%E5%8D%87%E5%90%8E%E9%99%8D%22%5D%0A%20%20G2%20--%3E%20G%0A%20%20G%20--%3E%20Q%7B%22%E7%BC%93%E8%A7%A3%E6%89%8B%E6%AE%B5%E5%8A%A8%E7%9A%84%E6%98%AF%E5%93%AA%E4%B8%AA%E9%BD%BF%E8%BD%AE%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%B0%83%E5%A4%A7%20%CE%B2%EF%BC%9A%E7%BB%99%E5%8E%8B%E5%8A%9B%E5%AE%9A%E4%BB%B7%22%7C%20SLOW%5B%22%E5%8F%AA%E5%87%8F%E9%80%9F%EF%BC%8C%E6%96%B9%E5%90%91%E4%B8%8D%E5%8F%98%22%5D%0A%20%20Q%20--%3E%7C%22%E9%9B%86%E6%88%90%20%2F%20%E6%A0%A1%E5%87%86%EF%BC%9A%E5%8E%8B%20%CE%B7%20%E6%96%B9%E5%B7%AE%22%7C%20SHIFT%5B%22%E5%8F%AA%E6%8C%AA%E6%8B%90%E7%82%B9%EF%BC%8C%E4%B8%8D%E6%B6%88%E7%81%AD%22%5D%0A%20%20Q%20--%3E%7C%22RLVR%EF%BC%9A%E6%8D%A2%E6%88%90%E9%AA%8C%E8%AF%81%E5%99%A8%22%7C%20HOST%5B%22%E9%BB%91%E5%AE%A2%E6%8D%A2%E5%AE%BF%E4%B8%BB%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">为什么重要：三个仪表各盯一件事——KL 告诉你走了多远，「代理减金标」告诉你缺口多大，压力旋钮（\\(\\beta\\)、步数、\\(N\\)）告诉你推得多狠。只盯一个（比如只看 KL 没超预算）会漏掉另外两个的恶化；三线同看才谈得上「还没失控」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>骨架的限度要说清。恒等式是定义不是定理，它不给 \\(r^\\star\\)；Skalse 的不可钻性条件需要知道 \\(r^\\star\\) 才能检验，实际上不可得，只能靠独立金标逼近。标度律是经验规律，换任务分布或换基座会移位，不能外推成定律。理论没有给出「安全阈值」，只给出三个可监控量的关系：压力（\\(\\beta\\)、步数、\\(N\\)）、间隙（双轴监控里的代理减金标）、支撑距离（KL）。把它们记成三个仪表，比记住任何一条曲线都有用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代理与真奖励之差是残差 \\(\\eta\\)；危险在于 \\(\\eta\\) 与 \\(\\tilde r\\) 相关，且优化器主动搜向 \\(\\eta\\) 偏正的极值尾部。</li><li>KL 正则解形如 \\(\\pi\\propto\\pi_{\\mathrm{ref}}\\exp(\\tilde r/\\beta)\\)：\\(\\beta\\)、PPO 步数、BoN 的 \\(N\\) 是同一个「压力」的三种货币。</li><li>Goodhart 放大 = 优化压力 × 离线外推；KL 是定价，集成与校准只挪拐点，RLVR 换宿主。</li><li>可钻性的严格定义来自 Skalse 等；标度律来自 Gao 等，两者都不给安全阈值，只给可监控量。</li><li>出处：Strathern 1997 对 Goodhart 定律的表述；Gao、Schulman、Hilton 2022；Skalse 等 2022。</li></ul>',5))])}const P=s(d,[["render",m]]);export{f as __pageData,P as default};
